param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop';$snapshotRoot=Join-Path $RepositoryRoot 'tests/e2e/frontend-operations-external/snapshots';$outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/operations-external-visual-baseline.json'
$snapshots=@(Get-ChildItem -LiteralPath $snapshotRoot -Filter 'PV-*.png'|Sort-Object Name);if($snapshots.Count -ne 5){throw "Expected exactly 5 external-management snapshots, found $($snapshots.Count)."}
$cases=foreach($snapshot in $snapshots){$pv=[IO.Path]::GetFileNameWithoutExtension($snapshot.Name);[ordered]@{pv=$pv;pageId=if($pv -eq 'PV-0005'){'operations.external.shell'}else{'operations.external'};testId="operations-external-visual.spec.ts::$pv";baselinePath=$snapshot.FullName.Substring($RepositoryRoot.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $snapshot.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$snapshot.Length}}
if(@($cases.sha256|Sort-Object -Unique).Count -lt 4){throw 'External-management snapshots must preserve the four distinct runtime states.'}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-visual-regression-baseline';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();contractVersion='operations-external-design-1.0';baselineVersion='operations-external-windows-chromium-v1';environment=[ordered]@{operatingSystem='Windows';browser='Chromium';viewport='1440x900';locale='zh-CN';timezone='Asia/Shanghai';colorScheme='light';reducedMotion=$true};businessAssertions=@('Fuxing Bank operations console maps the PV-0005 third-party shell reference to the truthful local external-management center without copying the source bank brand or inventing tenant metrics.','Fuxing Bank operations console covers PV-0198 through PV-0201 with loading, available, partial, and unavailable external-service states.','The page probes loopback-only Mifos X, Keycloak, and Grafana endpoints and never stores or displays credentials.','The supplied PV-0198-PV-0201 composite is mislabeled: its four panels show audit pages rather than external-management pages.','The accepted traceability matrix and live local-service evidence are therefore the authoritative implementation baseline for these states.','Visual fixtures are deterministic synthetic data and contain no real personal data or secrets.');cases=$cases}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
